import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX implementing a grouped / padded / dilated / strided
# ConvTranspose2d forward pass (float32 only).
#
# Structural optimization applied: CTA-level output tiling combined with
# shared-memory staging of the (small) per-group weight slice.
#
# Each CTA is responsible for a fixed (n, group) pair and a contiguous
# "chunk" of `blockDim.x` output elements within that (n, group)'s output
# volume (oc_local, oh, ow). Since the weight slice for a group
# (icpg * ocpg * kH * kW elements) is small and reused by every output
# element and every chunk belonging to that (n, group), every CTA first
# cooperatively loads its group's weight slice into shared memory once,
# synchronizes, and then all threads reuse it directly from shared memory
# for their accumulation instead of repeatedly hitting global memory /
# repeating expensive index arithmetic for weight addresses. Grid size is
# chosen so that overall parallelism (and therefore occupancy) closely
# matches the original one-thread-per-output mapping.
#
# Weight layout matches PyTorch's ConvTranspose2d weight layout:
#   W[Cin, Cout/groups, kH, kW]
# ---------------------------------------------------------------------------
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.extern .shared .align 4 .b8 smem_w[];

.visible .entry conv_transpose2d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 groups,
    .param .u32 icpg,
    .param .u32 ocpg,
    .param .u32 chunks_per_group
)
{
    .reg .pred %p<20>;
    .reg .f32  %f<10>;
    .reg .b32  %r<130>;
    .reg .b64  %rd<50>;

    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [y_ptr];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd4, %rd4;

    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [Cin];
    ld.param.u32 %r3,  [H];
    ld.param.u32 %r4,  [Win];
    ld.param.u32 %r5,  [Cout];
    ld.param.u32 %r6,  [Hout];
    ld.param.u32 %r7,  [Wout];
    ld.param.u32 %r8,  [kH];
    ld.param.u32 %r9,  [kW];
    ld.param.u32 %r10, [stride_h];
    ld.param.u32 %r11, [stride_w];
    ld.param.u32 %r12, [pad_h];
    ld.param.u32 %r13, [pad_w];
    ld.param.u32 %r14, [dil_h];
    ld.param.u32 %r15, [dil_w];
    ld.param.u32 %r16, [groups];
    ld.param.u32 %r17, [icpg];
    ld.param.u32 %r18, [ocpg];
    ld.param.u32 %r19, [chunks_per_group];

    mov.u32 %r20, %ctaid.x;
    div.s32 %r21, %r20, %r19;      // n_g_idx
    rem.s32 %r22, %r20, %r19;      // chunk_idx
    rem.s32 %r23, %r21, %r16;      // g
    div.s32 %r24, %r21, %r16;      // n

    mul.lo.s32 %r25, %r23, %r17;   // ic_base
    mul.lo.s32 %r26, %r23, %r18;   // oc_base

    mul.lo.s32 %r27, %r17, %r18;
    mul.lo.s32 %r27, %r27, %r8;
    mul.lo.s32 %r27, %r27, %r9;    // wsize = icpg*ocpg*kH*kW

    mul.lo.s32 %r28, %r23, %r27;   // w_base_idx = g * wsize

    // cooperative load of this group's weight slice into shared memory
    mov.u32 %r30, %tid.x;
    mov.u32 %r31, %ntid.x;

LOAD_LOOP:
    setp.ge.s32 %p1, %r30, %r27;
    @%p1 bra LOAD_DONE;

    add.s32 %r32, %r28, %r30;
    cvt.s64.s32 %rd10, %r32;
    shl.b64 %rd11, %rd10, 2;
    add.s64 %rd12, %rd2, %rd11;
    ld.global.f32 %f1, [%rd12];

    mov.u32 %r33, smem_w;
    mul.lo.s32 %r34, %r30, 4;
    add.s32 %r35, %r33, %r34;
    st.shared.f32 [%r35], %f1;

    add.s32 %r30, %r30, %r31;
    bra LOAD_LOOP;
LOAD_DONE:

    bar.sync 0;

    // compute assigned flattened output index i (within this n,group)
    mov.u32 %r40, %ntid.x;
    mul.lo.s32 %r41, %r22, %r40;   // local_start
    mov.u32 %r42, %tid.x;
    add.s32 %r43, %r41, %r42;      // i

    mul.lo.s32 %r44, %r18, %r6;
    mul.lo.s32 %r44, %r44, %r7;    // total_per_group = ocpg*Hout*Wout

    setp.ge.s32 %p2, %r43, %r44;
    @%p2 bra DONE_THREAD;

    // decode i -> ow, oh, oc_local
    rem.s32 %r50, %r43, %r7;      // ow
    div.s32 %r51, %r43, %r7;
    rem.s32 %r52, %r51, %r6;      // oh
    div.s32 %r53, %r51, %r6;      // oc_local

    add.s32 %r54, %r26, %r53;     // oc_global

    // bias
    setp.eq.s64 %p3, %rd3, 0;
    @%p3 bra BIAS_ZERO;
    cvta.to.global.u64 %rd13, %rd3;
    mul.wide.s32 %rd14, %r54, 4;
    add.s64 %rd15, %rd13, %rd14;
    ld.global.f32 %f2, [%rd15];
    bra BIAS_DONE;
BIAS_ZERO:
    mov.f32 %f2, 0f00000000;
BIAS_DONE:

    // idx_y = ((n*Cout+oc_global)*Hout+oh)*Wout+ow
    mad.lo.s32 %r55, %r24, %r5, %r54;
    mad.lo.s32 %r56, %r55, %r6, %r52;
    mad.lo.s32 %r57, %r56, %r7, %r50;

    mov.u32 %r60, 0;   // kh
KH_LOOP:
    setp.ge.s32 %p4, %r60, %r8;
    @%p4 bra KH_END;

    mul.lo.s32 %r61, %r60, %r14;
    add.s32 %r62, %r52, %r12;
    sub.s32 %r63, %r62, %r61;      // ih_num

    rem.s32 %r64, %r63, %r10;
    setp.ne.s32 %p5, %r64, 0;
    @%p5 bra KH_NEXT;

    div.s32 %r65, %r63, %r10;      // ih
    setp.lt.s32 %p6, %r65, 0;
    setp.ge.s32 %p7, %r65, %r3;
    or.pred %p8, %p6, %p7;
    @%p8 bra KH_NEXT;

    mov.u32 %r70, 0;   // kw
KW_LOOP:
    setp.ge.s32 %p9, %r70, %r9;
    @%p9 bra KW_END;

    mul.lo.s32 %r71, %r70, %r15;
    add.s32 %r72, %r50, %r13;
    sub.s32 %r73, %r72, %r71;      // iw_num

    rem.s32 %r74, %r73, %r11;
    setp.ne.s32 %p10, %r74, 0;
    @%p10 bra KW_NEXT;

    div.s32 %r75, %r73, %r11;      // iw
    setp.lt.s32 %p11, %r75, 0;
    setp.ge.s32 %p12, %r75, %r4;
    or.pred %p13, %p11, %p12;
    @%p13 bra KW_NEXT;

    mov.u32 %r80, 0;   // ic_local
IC_LOOP:
    setp.ge.s32 %p14, %r80, %r17;
    @%p14 bra IC_END;

    add.s32 %r81, %r25, %r80;      // ic_global

    // idx_x = ((n*Cin+ic_global)*H+ih)*Win+iw
    mad.lo.s32 %r82, %r24, %r2, %r81;
    mad.lo.s32 %r83, %r82, %r3, %r65;
    mad.lo.s32 %r84, %r83, %r4, %r75;

    cvt.s64.s32 %rd20, %r84;
    shl.b64 %rd21, %rd20, 2;
    add.s64 %rd22, %rd1, %rd21;
    ld.global.f32 %f3, [%rd22];

    // smem weight idx = ((ic_local*ocpg+oc_local)*kH+kh)*kW+kw
    mad.lo.s32 %r85, %r80, %r18, %r53;
    mad.lo.s32 %r86, %r85, %r8, %r60;
    mad.lo.s32 %r87, %r86, %r9, %r70;

    mov.u32 %r88, smem_w;
    mul.lo.s32 %r89, %r87, 4;
    add.s32 %r90, %r88, %r89;
    ld.shared.f32 %f4, [%r90];

    fma.rn.f32 %f2, %f3, %f4, %f2;

    add.s32 %r80, %r80, 1;
    bra IC_LOOP;
IC_END:

KW_NEXT:
    add.s32 %r70, %r70, 1;
    bra KW_LOOP;
KW_END:

KH_NEXT:
    add.s32 %r60, %r60, 1;
    bra KH_LOOP;
KH_END:

    cvt.s64.s32 %rd30, %r57;
    shl.b64 %rd31, %rd30, 2;
    add.s64 %rd32, %rd4, %rd31;
    st.global.f32 [%rd32], %f2;

DONE_THREAD:
    ret;
}
"""

_KERNEL_NAME = "conv_transpose2d_kernel"
_MODULE_CACHE = None


def _get_ptx_module():
    global _MODULE_CACHE
    if _MODULE_CACHE is None:
        _MODULE_CACHE = PtxModule(PTX_SOURCE)
    return _MODULE_CACHE


def validate_generated_code():
    """Compile-time / lookup-time sanity check for the embedded PTX module."""
    module = _get_ptx_module()
    fn = module.function(_KERNEL_NAME)
    assert fn is not None, f"entry point {_KERNEL_NAME} not found in PTX module"
    return True


class ModelNew(nn.Module):
    """
    2D transposed convolution (grouped, padded, dilated, asymmetric) implemented
    with a single hand-authored PTX kernel launched via cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        kH, kW = kernel_size
        ocpg = out_channels // groups

        # Weight layout matches PyTorch ConvTranspose2d: (in_channels, out_channels/groups, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, ocpg, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            icpg = self.in_channels // self.groups
            kH, kW = self.kernel_size
            fan_in = icpg * kH * kW
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, H, Win = x_c.shape
        Cin_w, ocpg, kH, kW = w_c.shape
        assert Cin_w == Cin, "weight.size(0) must equal Cin"

        groups = self.groups
        Cout = ocpg * groups
        icpg = Cin // groups
        assert icpg * groups == Cin, "Cin must be divisible by groups"

        stride_h, stride_w = self.stride
        pad_h, pad_w = self.padding
        dil_h, dil_w = self.dilation

        Hout = (H - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1
        Wout = (Win - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1
        assert Hout > 0 and Wout > 0, "Invalid output size computed"

        if self.bias is not None:
            b_c = self.bias.contiguous()
            assert b_c.dim() == 1 and b_c.size(0) == Cout, "bias must be [Cout]"
            bias_ptr = b_c.data_ptr()
        else:
            b_c = None
            bias_ptr = 0

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=torch.float32)

        threads = 256

        total_per_group = ocpg * Hout * Wout
        chunks_per_group = (total_per_group + threads - 1) // threads
        chunks_per_group = max(chunks_per_group, 1)

        blocks = N * groups * chunks_per_group
        blocks = max(blocks, 1)

        wsize = icpg * ocpg * kH * kW
        shared_mem_bytes = wsize * 4

        module = _get_ptx_module()
        kernel = module.function(_KERNEL_NAME)
        stream = torch.cuda.current_stream(device=x.device).cuda_stream

        module.launch(
            kernel,
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            shared_mem_bytes=shared_mem_bytes,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(bias_ptr),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(H), i32(Win),
                i32(Cout), i32(Hout), i32(Wout),
                i32(kH), i32(kW),
                i32(stride_h), i32(stride_w),
                i32(pad_h), i32(pad_w),
                i32(dil_h), i32(dil_w),
                i32(groups), i32(icpg), i32(ocpg),
                i32(chunks_per_group),
            ],
        )

        # Keep tensors alive until the launch has been recorded on the stream.
        del x_c, w_c, b_c

        return y

