    div.s32 %r61, %r60, %r7;    // oh
    rem.s32 %r62, %r60, %r7;    // ow

    mov.f32 %f3, %f1;           // acc = bias

    mov.u32 %r70, 0;            // kh
KH_LOOP:
    setp.ge.s32 %p5, %r70, %r8;
    @%p5 bra KH_END;

    mul.lo.s32 %r71, %r70, %r14;
    add.s32 %r72, %r61, %r12;
    sub.s32 %r73, %r72, %r71;   // ih_num

    rem.s32 %r74, %r73, %r10;
    setp.ne.s32 %p6, %r74, 0;
    @%p6 bra KH_NEXT;

    div.s32 %r75, %r73, %r10;   // ih
    setp.lt.s32 %p7, %r75, 0;
    setp.ge.s32 %p8, %r75, %r3;
    or.pred %p9, %p7, %p8;
    @%p9 bra KH_NEXT;

    mul.lo.s32 %r76, %r70, %r9; // kh*kW

    mov.u32 %r80, 0;            // kw
