_KERNEL_NAME = "conv_transpose2d_kernel"
_MODULE_CACHE = None


def _get_ptx_module():
    global _MODULE_CACHE
    if _MODULE_CACHE is None:
        _MODULE_CACHE = PtxModule(PTX_SOURCE)
    return _MODULE_CACHE


def validate_generated_code():
    """Compile-time / lookup-time sanity check for the embedded PTX module."""
    module = _get_ptx_module()
    fn = module.function(_KERNEL_NAME)
    assert fn is not None, f"entry point {_KERNEL_NAME} not found in PTX module"
    return True


class ModelNew(nn.Module):
    """
    2D transposed convolution (grouped, padded, dilated, asymmetric) implemented
    with a single hand-authored PTX kernel launched via cutegen.ptx_runtime.PtxModule.

    Structural optimization: one CTA per (n, oc) pair cooperatively stages the
    relevant weight slice into shared memory once, then all threads in the CTA
    reuse it while computing the (Hout, Wout) spatial outputs for that channel,
    eliminating redundant global-memory weight reloads present in the naive
    one-thread-per-output direct kernel.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        kH, kW = kernel_size
        ocpg = out_channels // groups

        # Weight layout matches PyTorch ConvTranspose2d: (in_channels, out_channels/groups, kH, kW)
        self.weight = nn.Parameter(torch.empty(in_channels, ocpg, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            icpg = self.in_channels // self.groups
            kH, kW = self.kernel_size
            fan_in = icpg * kH * kW
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, H, Win = x_c.shape
        Cin_w, ocpg, kH, kW = w_c.shape
        assert Cin_w == Cin, "weight.size(0) must equal Cin"

        groups = self.groups
        Cout = ocpg * groups
        icpg = Cin // groups
        assert icpg * groups == Cin, "Cin must be divisible by groups"

        stride_h, stride_w = self.stride
        pad_h, pad_w = self.padding
        dil_h, dil_w = self.dilation

        Hout = (H - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1
        Wout = (Win - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1
        assert Hout > 0 and Wout > 0, "Invalid output size computed"

        if self.bias is not None:
            b_c = self.bias.contiguous()
            assert b_c.dim() == 1 and b_c.size(0) == Cout, "bias must be [Cout]"
            bias_ptr = b_c.data_ptr()
        else:
            b_c = None
            bias_ptr = 0

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=torch.float32)

        threads = 256
        spatial = Hout * Wout
        blocks_x = (spatial + threads - 1) // threads
        blocks_x = max(blocks_x, 1)
        grid_y = N * Cout

        shared_bytes = icpg * kH * kW * 4

        module = _get_ptx_module()
        kernel = module.function(_KERNEL_NAME)
        stream = torch.cuda.current_stream(device=x.device).cuda_stream

        module.launch(
            kernel,
            grid=(blocks_x, grid_y, 1),
            block=(threads, 1, 1),
            shared_mem=shared_bytes,
            stream=stream,
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(bias_ptr),
                u64(y.data_ptr()),
                i32(N), i32(Cin), i32(H), i32(Win),
                i32(Cout), i32(Hout), i32(Wout),
                i32(kH), i32(kW),
                i32(stride_h), i32(stride_w),
                i32(pad_h), i32(pad_w),
                i32(dil_h), i32(dil_w),
                i32(groups), i32(icpg), i32(ocpg),
            ],
        )

        # Keep tensors alive until the launch has been recorded on the stream.
        del x_c, w_c, b_c

        return y

